"""Write sources.bzl from a Slang source tree.

Slang's CMake build lists almost none of its sources: slang_add_target()
globs each target's directory (cmake/Glob.cmake's slang_glob_sources), and
the generator steps glob their inputs (*.meta.slang, *-prelude.h, the
headers and sources slang-fiddle reads). This applies the same globs to the
tree and writes the results out as Starlark data for BUILD, which picks each
host's sources from them as slang_glob_sources() does (build.bzl's
host_sources()).

Usage:
    sources.py SRCDIR > sources.bzl
"""

import os
import sys

def glob_sources(root, directory):
    """The .cpp files under `directory`, as slang_glob_sources() finds them
    before it filters them by host. Only the .cpp files are compiled; headers
    are found through the include paths BUILD sets."""
    found = []
    for dirpath, dirnames, filenames in os.walk(os.path.join(root, directory)):
        for name in filenames:
            if name.endswith(".cpp"):
                found.append(os.path.relpath(os.path.join(dirpath, name), root))
    return sorted(found)


def glob_names(root, directory, suffixes):
    """The names of the files directly in `directory` ending in one of
    `suffixes`, as a non-recursive file(GLOB ...) finds them."""
    return sorted(
        name
        for name in os.listdir(os.path.join(root, directory))
        if name.endswith(suffixes) and os.path.isfile(os.path.join(root, directory, name))
    )


# tools/CMakeLists.txt's generator() targets this build needs.
GENERATORS = [
    "slang-capability-generator",
    "slang-embed",
    "slang-fiddle",
    "slang-generate",
    "slang-lookup-generator",
    "slang-spirv-embed-generator",
]


def main():
    root = sys.argv[1]
    data = {
        # source/core and source/compiler-core: the static libraries every
        # other target links.
        "CORE_SOURCES": glob_sources(root, "source/core"),
        "COMPILER_CORE_SOURCES": glob_sources(root, "source/compiler-core"),
        # source/slang/CMakeLists.txt's slang-common-objects, with the
        # record-replay layer it adds as EXTRA_SOURCE_DIRS.
        "SLANG_SOURCES": glob_sources(root, "source/slang")
        + glob_sources(root, "source/slang-record-replay"),
        # The inputs slang-fiddle scrapes: source/slang's own *.h and *.cpp.
        "FIDDLE_INPUTS": glob_names(root, "source/slang", (".h", ".cpp")),
        # slang-capability-generator's inputs.
        "CAPABILITY_DEFS": glob_names(root, "source/slang", (".capdef",)),
        # slang-generate's inputs, which become the embedded core module
        # source.
        "CORE_MODULE_META": glob_names(root, "source/slang", (".meta.slang",)),
        # The prelude headers slang-embed turns into C++ string literals.
        "PRELUDES": glob_names(root, "prelude", ("-prelude.h",)),
        # The public API headers.
        "PUBLIC_HEADERS": glob_names(root, "include", (".h",)),
        "GENERATOR_SOURCES": {
            name: glob_sources(root, "tools/" + name) for name in GENERATORS
        },
    }

    out = sys.stdout
    out.write("# SPDX-FileCopyrightText: © 2026 Austin Seipp\n")
    out.write("# SPDX-License-Identifier: Apache-2.0\n\n")
    out.write("# @generated by sources.py from Slang's source tree. Do not edit; see\n")
    out.write("# sources-up-to-date in BUILD.\n")
    for name, value in data.items():
        out.write("\n{} = {}\n".format(name, render(value, 0)))


def render(value, indent):
    """Starlark for a list of strings or a dict of them, formatted as
    buildifier would."""
    pad = "    " * (indent + 1)
    if isinstance(value, dict):
        items = ['{}"{}": {},\n'.format(pad, k, render(v, indent + 1)) for k, v in value.items()]
        return "{\n" + "".join(items) + "    " * indent + "}"
    if not value:
        return "[]"
    items = ['{}"{}",\n'.format(pad, v) for v in value]
    return "[\n" + "".join(items) + "    " * indent + "]"


if __name__ == "__main__":
    main()
